package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.repository.jobs.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.transaction.TransactionDefinition;
import org.springframework.transaction.support.TransactionTemplate;
import tools.jackson.databind.node.ObjectNode;

/** Actual native disposition lookup; new model values/allocation metadata are explicit fictional fixtures. */
class CatalogVersionJudgmentLedgerTest extends CatalogVersionJudgmentValueTest {
    CatalogVersionJudgmentValue.Value value(boolean recommend){var p=projection();var i=input(p);return CatalogVersionJudgmentValue.create(p,i,result(i,payload(p,recommend))).orElseThrow();}
    CatalogVersionJudgmentLedger ledger(){return new CatalogVersionJudgmentLedger(new JdbcCatalogVersionJudgments(f.source),f.category);}
    Optional<CatalogVersionJudgmentLedger.Stored> stored(String key){var tx=new TransactionTemplate(f.tx);tx.setReadOnly(true);tx.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);return tx.execute(s->ledger().read(key));}
    void seed(CatalogVersionJudgmentValue.Value v,Long generation,String intent){String payload=CatalogVersionJudgmentLedger.receipt(v,generation,intent,f.clock.instant());f.writes.execute(new SharedWriteExecutor.ActionContext("fictional-judgment-seed","fictional-root","c".repeat(64)),k->null,s->{new JdbcJobRecords(f.source).appendDispositionUtc(new JdbcJobRecords.Disposition(JdbcCatalogVersionJudgments.id(v.judgmentKey()),JdbcCatalogVersionJudgments.action(v.judgmentKey()),JdbcCatalogVersionJudgments.TYPE,JdbcCatalogVersionJudgments.target(v.judgmentKey()),JdbcCatalogVersionJudgments.ACTOR,JdbcCatalogVersionJudgments.REASON,payload),f.clock.instant());return true;});}
    void alterPayload(String key,java.util.function.Consumer<ObjectNode> edit){String id=JdbcCatalogVersionJudgments.id(key);var n=(ObjectNode)CanonicalJson.parse(f.jdbc.queryForObject("SELECT action_payload FROM jobs WHERE id=?",String.class,id));edit.accept(n);String raw=JdbcFrozenInputs.canonical(n);f.jdbc.update("UPDATE jobs SET action_payload=?,action_payload_hash=? WHERE id=?",raw,JdbcGenerationLineage.hash(raw),id);}
    @Test void FourNativeCategoriesReadOriginalPermanentDecisionAfterAllCurrentProofsChange(){for(String cat:List.of("agent","skill","workflow","model")){initialize(cat,false);var v=value(false);assertTrue(stored(v.judgmentKey()).isEmpty());seed(v,null,null);var first=stored(v.judgmentKey()).orElseThrow();assertEquals("changed_declined",first.verdict());assertNull(first.generation());assertEquals(v.hash(),first.judgmentHash());current.put("summary","Fictional later metadata");update();f.jdbc.update("UPDATE analyzed_entities SET analysis_generation=3,revision=revision+1");f.jdbc.update("DELETE FROM source_runs");assertEquals(first.json(),stored(v.judgmentKey()).orElseThrow().json());assertFalse(first.toString().contains("fictional"));assertEquals(1,f.sends);}}
    @Test void NativeCanonicalHashesClosedRoleAndUtcTimestampCorruptionAreRejected(){for(String field:List.of("record_identity_hash","target_key_hash","action_key_hash","action_payload_hash")){initialize("agent",false);var v=value(false);seed(v,null,null);f.jdbc.update("UPDATE jobs SET "+field+"=? WHERE id=?",new byte[32],JdbcCatalogVersionJudgments.id(v.judgmentKey()));assertThrows(RuntimeException.class,()->stored(v.judgmentKey()));}for(String sql:List.of("record_kind='snapshot_part',owner_job_id='fictional-root',purpose='review',stamp_id='fictional-wrong-role',part_no=0,payload_json='{}',payload_hash=action_payload_hash","target_type='worker_claim'","operator_id='fictional-foreign'","reason='Fictional foreign'","state='failed'","revision=1","acted_at='2026-01-03 00:00:00'")){initialize("agent",false);var v=value(false);seed(v,null,null);f.jdbc.update("UPDATE jobs SET "+sql+" WHERE id=?",JdbcCatalogVersionJudgments.id(v.judgmentKey()));assertThrows(RuntimeException.class,()->stored(v.judgmentKey()));}}
    @Test void RehashedBadSemanticKeyFlagsAllocationAndExtraFieldsRemainRejected(){for(String fault:List.of("key","flag","refs","allocation","extra")){initialize("agent",false);var v=value(false);seed(v,null,null);alterPayload(v.judgmentKey(),n->{var j=(ObjectNode)n.get("judgment_value");switch(fault){case "key"->j.put("version_hash","e".repeat(64));case "flag"->j.put("version_changed",false);case "refs"->((ObjectNode)j.get("new_evidence_ref")).put("kind","catalog_evidence");case "allocation"->n.put("allocated_generation",2);case "extra"->n.put("unexpected",true);}n.put("judgment_value_hash",CanonicalJson.hash(CanonicalJson.Domain.ACTION,j));});assertThrows(RuntimeException.class,()->stored(v.judgmentKey()));}}
    @Test void PureReceiptRequiresExactKnownVerdictAndAllocationPairWithoutGrantingNativeAuthority(){var positive=value(true);assertThrows(RuntimeException.class,()->CatalogVersionJudgmentLedger.receipt(positive,null,null,f.clock.instant()));assertThrows(RuntimeException.class,()->CatalogVersionJudgmentLedger.receipt(positive,0L,"fictional-intent",f.clock.instant()));seed(positive,2L,"fictional-intent");var actual=stored(positive.judgmentKey()).orElseThrow();assertEquals(2L,actual.generation());assertEquals("fictional-intent",actual.intentId());assertEquals(1,f.jdbc.queryForObject("SELECT analysis_generation FROM analyzed_entities",Integer.class));assertEquals(1,f.sends);}
    @Test void OriginalSqlCapacityAndReadonlyOrWriterTransactionBoundariesCannotBeBypassed(){var v=value(false);seed(v,null,null);var nativeStore=new JdbcCatalogVersionJudgments(f.source);assertThrows(RuntimeException.class,()->nativeStore.read(v.judgmentKey()));assertThrows(RuntimeException.class,()->nativeStore.lockAndRead(v.judgmentKey()));var wrong=new TransactionTemplate(f.tx);wrong.setReadOnly(true);wrong.setIsolationLevel(TransactionDefinition.ISOLATION_SERIALIZABLE);assertThrows(RuntimeException.class,()->wrong.execute(s->ledger().read(v.judgmentKey())));f.writes.execute(new SharedWriteExecutor.ActionContext("fictional-judgment-read","fictional-root","c".repeat(64)),k->null,s->{assertEquals(storedHash(v),ledger().lockAndRead(v.judgmentKey()).orElseThrow().judgmentHash());assertThrows(RuntimeException.class,()->ledger().read(v.judgmentKey()));return true;});String id=JdbcCatalogVersionJudgments.id(v.judgmentKey());f.jdbc.update("UPDATE jobs SET action_payload=? WHERE id=?","{\"fictional_padding\":\""+"z".repeat(32768)+"\"}",id);var tx=new TransactionTemplate(f.tx);tx.setReadOnly(true);tx.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);assertNull(tx.execute(s->nativeStore.read(v.judgmentKey())).payload());assertThrows(RuntimeException.class,()->stored(v.judgmentKey()));}
    String storedHash(CatalogVersionJudgmentValue.Value v){return v.hash();}
}
